// === Tab: mySketch.js ===
/**
 * @name 04_multiple_asciifiers
 * @description Basic example applying multiple asciifiers on various textures in parallel with p5.js and p5.asciify.
 * @author humanbydefinition
 * @link https://github.com/humanbydefinition/p5.asciify
 * 
 * This example demonstrates how to apply multiple asciifiers on various textures in parallel.
 * The pre-defined 'brightness' renderer by the default asciifier is used to asciify the canvas.
 * A custom asciifier is created and applied to a custom framebuffer.
 */

// Options for the default brightness asciifier
const DEFAULT_BRIGHTNESS_OPTIONS = {
  enabled: true,
  characters: " .:-=+*#%@",
  characterColor: "#ffffff",
  characterColorMode: 'sampled',
  backgroundColor: "#000000",
  backgroundColorMode: 'fixed',
  invertMode: false,
  fontSize: 16,
  rotationAngle: 0
};

// Options for the custom brightness asciifier
const CUSTOM_BRIGHTNESS_OPTIONS = {
  enabled: true,
  characters: " .:oO@",
  characterColor: "#ffffff",
  characterColorMode: 'sampled',
  backgroundColor: "#000000",
  backgroundColorMode: 'fixed',
  invertMode: true,
  fontSize: 32,
  rotationAngle: 0
};

// Global variables
let defaultAsciifier; // Define a variable to store the default `P5Asciifier` instance
let customAsciifier; // Define a variable to store the custom `P5Asciifier` instance
let customFramebuffer; // Framebuffer the custom asciifier will asciify

function setup() {
  setAttributes('antialias', false);
  createCanvas(windowWidth, windowHeight, WEBGL);
}

// After `p5.asciify` is set up in the background after `setup()`,
// we can call `setupAsciify()` to configure `p5asciify` and it's `P5Asciifier` instances and rendering pipelines
function setupAsciify() {
  // Fetch the default `P5Asciifier` instance provided by the library
  defaultAsciifier = p5asciify.asciifier();

  // Create a new asciifier instance and apply it to a custom framebuffer
  customFramebuffer = createFramebuffer();
  customAsciifier = p5asciify.add(customFramebuffer);

  // Set the font size for both asciifiers
  defaultAsciifier.fontSize(DEFAULT_BRIGHTNESS_OPTIONS.fontSize);
  customAsciifier.fontSize(CUSTOM_BRIGHTNESS_OPTIONS.fontSize);

  // Update the default asciifiers default 'brightness' renderer with the provided options
  defaultAsciifier.renderers().get("brightness").update({
    enabled: DEFAULT_BRIGHTNESS_OPTIONS.enabled,
    characters: DEFAULT_BRIGHTNESS_OPTIONS.characters,
    characterColor: DEFAULT_BRIGHTNESS_OPTIONS.characterColor,
    characterColorMode: DEFAULT_BRIGHTNESS_OPTIONS.characterColorMode,
    backgroundColor: DEFAULT_BRIGHTNESS_OPTIONS.backgroundColor,
    backgroundColorMode: DEFAULT_BRIGHTNESS_OPTIONS.backgroundColorMode,
    invertMode: DEFAULT_BRIGHTNESS_OPTIONS.invertMode,
    rotationAngle: DEFAULT_BRIGHTNESS_OPTIONS.rotationAngle
  });

  // Update the custom asciifiers default 'brightness' renderer with the provided options
  customAsciifier.renderers().get("brightness").update({
    enabled: CUSTOM_BRIGHTNESS_OPTIONS.enabled,
    characters: CUSTOM_BRIGHTNESS_OPTIONS.characters,
    characterColor: CUSTOM_BRIGHTNESS_OPTIONS.characterColor,
    characterColorMode: CUSTOM_BRIGHTNESS_OPTIONS.characterColorMode,
    backgroundColor: CUSTOM_BRIGHTNESS_OPTIONS.backgroundColor,
    backgroundColorMode: CUSTOM_BRIGHTNESS_OPTIONS.backgroundColorMode,
    invertMode: CUSTOM_BRIGHTNESS_OPTIONS.invertMode,
    rotationAngle: CUSTOM_BRIGHTNESS_OPTIONS.rotationAngle
  });

  // Make the background of both asciifiers fully transparent.
  defaultAsciifier.background([0, 0, 0, 0]);
  customAsciifier.background([0, 0, 0, 0]);
}

function draw() {
  directionalLight(255, 255, 255, 0, 0, -1);

  // Draw anything on the custom framebuffer for the custom asciifier to asciify
  customFramebuffer.begin();
  clear();
  fill(255);
  rotateX(radians(frameCount * 3));
  rotateZ(radians(frameCount));
  box(800, 100, 100);
  customFramebuffer.end();

  // Draw anything on the canvas for the default asciifier to asciify
  clear();
  normalMaterial();
  rotateX(radians(frameCount * 3));
  rotateY(radians(frameCount));
  torus(300, 100);
}

// After the asciified content is drawn to the canvas, use `drawAsciify()` to draw on top of it
function drawAsciify() {
  background(0); // Set the background to black, removing everything previously drawn

  // Draw both asciifier textures on top of each other
  image(defaultAsciifier.texture, -width / 2, -height / 2);
  image(customAsciifier.texture, -width / 2, -height / 2);

  // Draw the FPS counter
  const fpsText = "FPS:" + Math.min(Math.ceil(frameRate()), 60);

  noStroke();
  fill(0);
  rect(-width / 2, height / 2 - textAscent() - 4, textWidth(fpsText), textAscent());

  textFont(defaultAsciifier.fontManager.font);
  textSize(64);
  fill(255, 255, 0);
  text(fpsText, -width / 2, height / 2);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

